class BankAccount {
    private String accountId;
    private double balance;

    public BankAccount(String accountId, double balance) {
        this.accountId = accountId;
        this.balance = balance;
    }

    public boolean debit(double amount) {
        if (amount > 0 && balance >= amount) {
            balance -= amount;
            return true;
        }
        return false;
    }

    public void credit(double amount) {
        if (amount > 0) balance += amount;
    }

    public String getStatement() {
        return accountId + " | Balance: $" + balance;
    }
}

class TransferCoordinator {
    // Stateless orchestrator method collaborating with two BankAccount objects
    public boolean executeTransfer(BankAccount sender, BankAccount receiver, double amount) {
        System.out.println("Initiating transfer of $" + amount);
        if (sender.debit(amount)) {
            receiver.credit(amount);
            System.out.println("Transfer successful!");
            return true;
        } else {
            System.out.println("Transfer failed: Insufficient funds!");
            return false;
        }
    }
}

public class CollaborationDemo {
    public static void main(String[] args) {
        BankAccount accA = new BankAccount("ACC-101", 500.0);
        BankAccount accB = new BankAccount("ACC-202", 150.0);

        TransferCoordinator service = new TransferCoordinator();
        service.executeTransfer(accA, accB, 200.0);

        System.out.println(accA.getStatement());
        System.out.println(accB.getStatement());
    }
}

