class InventoryService {
    public boolean checkAndReserve(String itemCode) {
        System.out.println("[Inventory] Item " + itemCode + " reserved.");
        return true;
    }
}

class PaymentGateway {
    public boolean charge(String customerEmail, double amount) {
        System.out.println("[Payment] Charged $" + amount + " to " + customerEmail);
        return true;
    }
}

class NotificationService {
    public void sendReceipt(String email, String details) {
        System.out.println("[Notification] Email sent to " + email + ": " + details);
    }
}

class CheckoutManager {
    private InventoryService inventory;
    private PaymentGateway payment;
    private NotificationService notifier;

    public CheckoutManager(InventoryService inv, PaymentGateway pay, NotificationService notif) {
        this.inventory = inv;
        this.payment = pay;
        this.notifier = notif;
    }

    public void processOrder(String email, String itemCode, double amount) {
        if (inventory.checkAndReserve(itemCode) && payment.charge(email, amount)) {
            notifier.sendReceipt(email, "Order confirmed for " + itemCode);
        }
    }
}

public class PipelineDemo {
    public static void main(String[] args) {
        CheckoutManager checkout = new CheckoutManager(
            new InventoryService(), 
            new PaymentGateway(), 
            new NotificationService()
        );
        checkout.processOrder("buyer@domain.com", "SKU-LAPTOP-X", 1299.00);
    }
}

