class Driver {
    private String name;
    private boolean available = true;
    public Driver(String name) {
        this.name = name;
    }
    public boolean isAvailable() { return available; }
    public void assignRide() { this.available = false; }
    public String getName() { return name; }
}

class Passenger {
    private String name;
    private String destination;
    public Passenger(String name, String destination) {
        this.name = name;
        this.destination = destination;
    }
    public String getName() { return name; }
    public String getDestination() { return destination; }
}

class DispatchService {
    public boolean dispatch(Driver driver, Passenger passenger) {
        if (driver.isAvailable()) {
            driver.assignRide();
            System.out.println("[Dispatch] Driver " + driver.getName() + " assigned to " + passenger.getName() + " heading to " + passenger.getDestination());
            return true;
        } else {
            System.out.println("[Dispatch] Driver " + driver.getName() + " is currently busy!");
            return false;
        }
    }
}

public class RideShareApp {
    public static void main(String[] args) {
        Driver driver = new Driver("Dave");
        Passenger p1 = new Passenger("Carol", "Airport");
        Passenger p2 = new Passenger("Dan", "Downtown");

        DispatchService service = new DispatchService();
        service.dispatch(driver, p1);
        service.dispatch(driver, p2);
    }
}

class Wallet {
    private String owner;
    private double balance;
    public Wallet(String owner, double balance) {
        this.owner = owner;
        this.balance = balance;
    }
    public String getOwner() { return owner; }
    public boolean withdraw(double amt) {
        if (amt > 0 && balance >= amt) {
            balance -= amt;
            return true;
        }
        return false;
    }
    public void deposit(double amt) {
        if (amt > 0) balance += amt;
    }
    public String getBalanceReport() {
        return owner + ": $" + balance;
    }
}

class P2PExchange {
    public void sendMoney(Wallet from, Wallet to, double amt) {
        if (from.withdraw(amt)) {
            to.deposit(amt);
            System.out.println("[P2P] Sent $" + amt + " from " + from.getOwner() + " to " + to.getOwner());
        } else {
            System.out.println("[P2P] Transfer failed: Insufficient balance");
        }
    }
}

public class P2PApp {
    public static void main(String[] args) {
        Wallet wA = new Wallet("Sam", 100.0);
        Wallet wB = new Wallet("Robin", 25.0);

        P2PExchange exchange = new P2PExchange();
        exchange.sendMoney(wA, wB, 40.0);
        exchange.sendMoney(wA, wB, 80.0);

        System.out.println(wA.getBalanceReport());
        System.out.println(wB.getBalanceReport());
    }
}

