class CreditCard {
    private String cardNum;
    private double balance;
    public CreditCard(String cardNum, double balance) { this.cardNum = cardNum; this.balance = balance; }

    // BUG: Exposing internal state and raw setter encourages 'Ask, Don't Tell'
    public double getBalance() { return balance; }
    public void setBalance(double b) { this.balance = b; }
    public String getCardNum() { return cardNum; }
}

class AccountManager {
    // BAD: Asking for balance, computing interest outside, setting balance back!
    public void chargeMonthlyInterest(CreditCard card, double ratePercent) {
        double current = card.getBalance();
        double interest = current * (ratePercent / 100.0);
        card.setBalance(current + interest);
        System.out.println("Applied interest: $" + interest + " | New Balance: $" + card.getBalance());
    }
}

public class TellDontAskBugApp {
    public static void main(String[] args) {
        CreditCard card = new CreditCard("4111-2222", 1000.0);
        AccountManager mgr = new AccountManager();
        mgr.chargeMonthlyInterest(card, 2.5);
    }
}

