class BuildArtifact {
    private String artifactName;
    private boolean compiled = false;
    public BuildArtifact(String artifactName) {
        this.artifactName = artifactName;
    }
    public void compile() {
        this.compiled = true;
        System.out.println("[Builder] Compiled artifact: " + artifactName);
    }
    public boolean isCompiled() { return compiled; }
    public String getArtifactName() { return artifactName; }
}

class SecurityScanner {
    public boolean scan(BuildArtifact artifact) {
        if (artifact.isCompiled()) {
            System.out.println("[SecScanner] Vulnerability scan PASSED for " + artifact.getArtifactName());
            return true;
        }
        return false;
    }
}

class CloudDeployer {
    public void deploy(BuildArtifact artifact, String clusterName) {
        System.out.println("[Deployer] Released " + artifact.getArtifactName() + " to Kubernetes cluster: " + clusterName);
    }
}

class DeploymentPipeline {
    private SecurityScanner scanner;
    private CloudDeployer deployer;

    public DeploymentPipeline(SecurityScanner scanner, CloudDeployer deployer) {
        this.scanner = scanner;
        this.deployer = deployer;
    }

    public void runPipeline(BuildArtifact artifact, String cluster) {
        artifact.compile();
        if (scanner.scan(artifact)) {
            deployer.deploy(artifact, cluster);
        }
    }
}

public class CloudApp {
    public static void main(String[] args) {
        BuildArtifact artifact = new BuildArtifact("AuthService-v2.jar");
        SecurityScanner scanner = new SecurityScanner();
        CloudDeployer deployer = new CloudDeployer();
        DeploymentPipeline pipeline = new DeploymentPipeline(scanner, deployer);

        pipeline.runPipeline(artifact, "us-east-prod");
    }
}
